    c+=(s.mabooj||0)*maboojUnitCost()+(s.torshi||0)*torshiUnitCost()+(s.rice||0)*riceUnitCost();
    const t=S.tamur, p=Math.floor(1000/(t.tubG||1))||1; c+=(s.tamur||0)*(Math.round(t.kgCost/p)+(t.tubCost||0));
    const sc=s.sauce||{}; ['red','black'].forEach(k=>{ const n=sc[k]||0; if(n) (S.sauces[k].items||[]).forEach(it=>{ c+=n*(+it.use||0)*(it.grams?it.price/it.grams:0) }) });
