.pay-row button.on{background:#F5F5F2;color:#111;border-color:#F5F5F2;font-weight:700}
.loyal-box{grid-column:1/-1;padding:10px 12px;border-radius:12px;background:rgba(245,192,74,.12);color:#F5C04A;font-size:14px;font-weight:600;display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.loyal-box.dim{background:transparent;border:1px dashed #2a2c33;color:#9296A0;font-weight:400;font-size:13px}
.loyal-box button{margin-inline-start:auto;min-height:36px;padding:0 12px;border-radius:10px;border:0;background:#F5C04A;color:#111;font:inherit;font-weight:700;cursor:pointer}
.buy-tabs{display:flex;gap:6px;max-width:640px;margin-bottom:14px}.buy-tabs button{flex:1;min-height:46px}
.buy-x{display:none;max-width:760px}
